contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value) public payable {
        require(target != address(c));
        require(value <= address(c).balance);

        uint cBalBefore = address(c).balance;
        uint targetBalBefore = target.balance;

        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (
            address(c).balance == cBalBefore - value &&
            target.balance == targetBalBefore + value
        ));
    }

    receive() external payable {}
}

